namespace {
using Json=nlohmann::json;
Json load_json(const std::filesystem::path&path){std::ifstream f(path,std::ios::binary);std::vector<uint8_t>b{std::istreambuf_iterator<char>(f),{}};const auto n=vrm_source_fixture::word(b,12);return Json::parse(b.begin()+20,b.begin()+20+n);}
std::string native_role(std::string name){for(const char*side:{"left","right"}){if(name==std::string(side)+"ThumbProximal")return std::string(side)+"ThumbMetacarpal";if(name==std::string(side)+"ThumbIntermediate")return std::string(side)+"ThumbProximal";}return name;}
void hints(const std::filesystem::path&path){const auto j=load_json(path);std::map<std::string,size_t>roles;for(const auto&b:j.at("extensions").at("VRM").at("humanoid").at("humanBones"))roles.emplace(native_role(b.at("bone").get<std::string>()),b.at("node").get<size_t>());size_t tables=0,refs=0;for(const auto&node:j.at("nodes")){if(!node.contains("extras")||!node.at("extras").is_object()||!node.at("extras").contains("domeSculptHumanoid"))continue;++tables;for(const auto&binding:node.at("extras").at("domeSculptHumanoid").at("humanBones").items()){++refs;const auto id=binding.value().at("node").get<size_t>();if(!roles.contains(binding.key())||roles.at(binding.key())!=id)throw std::runtime_error("Native typed humanoid hint does not identify the actual emitted VRM role target");}}check(tables==1&&refs==54,"All54 source native humanoid node references match independently read current VRM metadata");}
void ready(Document&doc){if(!doc.wait_asset(std::chrono::seconds(180))||!doc.wait_mesh(std::chrono::seconds(180)))throw std::runtime_error("Native source-hint worker did not settle");if(!doc.frame().state->error.empty())throw std::runtime_error(doc.frame().state->error);}
}
